const categories = [
  'All Destinations',
  'Beach & Coastal',
  'Cultural & Historical',
  'Nature & Wildlife',
  'Marine & Water Adventure',
];

export default function DestinationsPage() {
  const [activeCategory, setActiveCategory] = useState('All Destinations');

  const filteredPlaces =
    activeCategory === 'All Destinations'
      ? mockPlaces
      : mockPlaces.filter((place) => place.category === activeCategory);

  return (
    <main className="min-h-screen">
      <Header />

      <div className="pt-24 bg-gradient-to-b from-emerald-50 to-white">
        <div className="container mx-auto px-4">
          <div className="text-center">
            <h1 className="text-5xl font-bold text-emerald-800 mb-4">Popular Destinations</h1>
            <p className="text-xl text-gray-600 max-w-2xl mx-auto">
              Explore breathtaking locations and discover your next adventure
            </p>
          </div>
        </div>
      </div>

      {/* Category Filter Buttons */}
      <section className="py-8 border-b border-gray-200">
        <div className="container mx-auto px-4">
          <div className="flex flex-wrap gap-4 justify-center">
            {categories.map((category) => (
              <Button
                key={category}
                onClick={() => setActiveCategory(category)}
                variant={activeCategory === category ? 'default' : 'outline'}
                className={`px-6 py-2 rounded-full font-semibold transition-all ${
                  activeCategory === category
                    ? 'bg-emerald-600 text-white hover:bg-emerald-700'
                    : 'border-emerald-600 text-emerald-600 hover:bg-emerald-50'
                }`}
              >
                {category}
              </Button>
            ))}
          </div>
        </div>
      </section>

      <section className="py-16">
        <div className="container mx-auto px-4">
          {filteredPlaces.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {filteredPlaces.map((place) => (
                <PlaceCard key={place.name} {...place} />
              ))}
            </div>
          ) : (
            <div className="text-center py-12">
              <p className="text-xl text-gray-600">No destinations found in this category.</p>
            </div>
          )}
        </div>
      </section>

      <Footer />
    </main>
  );
}
